import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';

export async function runMotionIsoOrbitSmoke(page){
 const viewport=page.viewport(),previous=await page.evaluate(()=>({project:JSON.stringify(project),curPage,curSec,curEl,curPane,selection,secFocus,mode:NAGWEB_STORY_EDITOR.canvasMode(),timeline:NAGWEB_STORY_TIMELINE_UI.state()})),dir=await fs.mkdtemp(path.join(os.tmpdir(),'nagweb-iso-orbit-')),file=path.join(dir,'Propia.svg');
 await fs.writeFile(file,'<svg xmlns="http://www.w3.org/2000/svg" width="300" height="180"><rect width="300" height="180" fill="#f2ae88"/><circle cx="150" cy="90" r="55" fill="#252932"/></svg>');await fs.mkdir('/tmp/nagweb-motion-visuals',{recursive:true});
 async function ready(){await page.waitForFunction(()=>{const f=document.querySelector('.nw-motion-dialog iframe'),d=f?.contentDocument;return d?.querySelectorAll('.nw-orbit-card').length===9&&d.querySelector('[data-motion-canvas]')&&Array.from(d.querySelectorAll('[data-nw-stream-slot] img')).every(n=>n.complete&&n.naturalWidth>0)&&Array.from(d.querySelectorAll('.nw-orbit-card')).every(n=>n.width>10);},{timeout:15000});}
 let revision=0;async function change(selector,value){const mark='orbit-'+(++revision);await page.$eval(selector,(n,{value,mark})=>{document.querySelector('.nw-motion-dialog iframe').contentDocument.body.dataset.orbitBefore=mark;n.value=value;n.dispatchEvent(new Event('change',{bubbles:true}));},{value,mark});await page.waitForFunction(mark=>{const d=document.querySelector('.nw-motion-dialog iframe')?.contentDocument;return d?.body&&d.body.dataset.orbitBefore!==mark&&d.querySelector('.nw-orbit-card')?.width>10;},{timeout:10000},mark);await ready();}
 async function pose(p,selector='.nw-motion-dialog iframe',gid){return page.$eval(selector,(f,{p,gid})=>{const d=f.contentDocument,id=gid||d.querySelector('.sc').dataset.id;f.contentWindow.__NAG_SCROLL_DIRECTOR[id].set(p);return Array.from(d.querySelectorAll('[data-nw-stream-slot]'),n=>({id:n.dataset.id,left:n.style.left,top:n.style.top,width:n.style.width,height:n.style.height,depth:n.dataset.nwStreamDepth,phase:n.dataset.nwStreamPhase,src:n.querySelector('img').getAttribute('src')}));},{p,gid});}
 async function capture(name){await page.$eval('.nw-motion-inspector-scroll',n=>n.scrollTop=0);await (await page.$('.nw-motion-dialog')).screenshot({path:'/tmp/nagweb-motion-visuals/iso-orbit-'+name+'.png'});}
 async function exported(gid){await page.evaluate(()=>{document.querySelector('#iso-grid-export')?.remove();const f=document.createElement('iframe');f.id='iso-grid-export';f.style.cssText='width:1280px;height:720px';f.srcdoc=generateSite(flattenPage(page()),false,false,false);document.body.append(f);});await page.waitForFunction(gid=>document.querySelector('#iso-grid-export')?.contentWindow?.__NAG_SCROLL_DIRECTOR?.[gid]&&document.querySelector('#iso-grid-export').contentDocument.querySelector('.nw-orbit-card')?.width>10,{},gid);}
 async function actualScroll(selector,gid){await page.$eval(selector,f=>f.contentWindow.scrollTo(0,f.contentDocument.querySelector('.sc').offsetHeight/2-f.contentWindow.innerHeight/2));await page.waitForFunction(({selector,gid})=>document.querySelector(selector).contentWindow.__NAG_SCROLL_DIRECTOR[gid].progress()>.4,{},{selector,gid});const middle=await page.$eval(selector,(f,gid)=>({p:f.contentWindow.__NAG_SCROLL_DIRECTOR[gid].progress(),phase:+f.contentDocument.querySelector('[data-nw-stream-slot]').dataset.nwStreamPhase}),gid);assert.ok(Math.abs(middle.phase-(middle.p*100-20)/60*3)<.001);await page.$eval(selector,f=>f.contentWindow.scrollTo(0,0));await page.waitForFunction(({selector,gid})=>document.querySelector(selector).contentWindow.__NAG_SCROLL_DIRECTOR[gid].progress()<.05,{},{selector,gid});assert.equal(await page.$eval(selector,f=>f.contentDocument.querySelector('[data-nw-stream-slot]').dataset.nwStreamPhase),'0.000000');}
 try{
  await page.evaluate(()=>{const outside=mkEl('label',{name:'Exterior',text:'Fuera de la grilla'});project.pages[0].sections=[mkSection({layout:'free',sdEnabled:false,bg:'#527467',elements:[outside]})];curPage=0;curSec=0;curEl=0;selection=[];secFocus=false;saveProject();renderPane();renderPreview();history=[];future=[];});const before=await page.evaluate(()=>({project:JSON.stringify(project),stored:localStorage.getItem(STORE_KEY),outside:sec().elements[0]}));
  await page.click('.tb-left [data-motion-open]');await page.click('[data-motion-template="iso-orbit"]');await ready();assert.equal(await page.$eval('[data-motion-stream="motion"]',n=>n.value),'swing');assert.equal(await page.$eval('[data-motion-stream="backgroundType"]',n=>n.value),'none');assert.equal(await page.$eval('[data-motion-config="duration"]',n=>n.value),'10');
  const start=await pose(0),end=await pose(1);assert.deepEqual(start.map(({phase,...n})=>n),end.map(({phase,...n})=>n));assert.notDeepEqual(await pose(.25),start);await pose(0);
  const filled=await page.$eval('.nw-motion-dialog iframe',f=>Array.from(f.contentDocument.querySelectorAll('.nw-orbit-card'),n=>n.getContext('2d').getImageData(Math.floor(n.width/2),Math.floor(n.height/2),1,1).data[3]));assert.ok(filled.every(n=>n>0),'All nine images are actually painted');
  // Select every actual image center, including planes overlapped by other bounding boxes.
  const frame=await (await page.$('.nw-motion-dialog iframe')).contentFrame();for(const card of start){await (await frame.$('[data-id="'+card.id+'"]')).click();assert.equal(await page.$eval('[data-motion-layer][aria-pressed="true"]',n=>n.dataset.motionLayer),card.id);}
  assert.equal(await page.$eval('[data-motion-duplicate]',n=>n.disabled),true);assert.equal(await page.$eval('[data-motion-element-remove]',n=>n.disabled),true,'The composition keeps its fixed 3×3 grid');
  await page.click('[data-motion-library-tab="elements"]');await page.click('[data-motion-layer="'+start[0].id+'"]');await capture('desktop');await change('[data-motion-stream-order]','9');assert.equal((await pose(0)).at(-1).id,start[0].id);await change('[data-motion-stream-order]','1');const uploadIndex=await page.$eval('[data-motion-content-panel] .crow:not([hidden]) [data-motion-upload]',n=>n.dataset.motionUpload);await (await page.$('[data-motion-upload="'+uploadIndex+'"]')).uploadFile(file);await page.waitForFunction(id=>document.querySelector('.nw-motion-dialog iframe')?.contentDocument?.querySelector('[data-id="'+id+'"] img')?.naturalWidth===300,{},start[0].id);await ready();
  const old=await pose(.2);await change('[data-motion-stream="spacing"]','40');await change('[data-motion-stream="tilt"]','70');await change('[data-motion-stream="orbitSize"]','90');await change('[data-motion-stream="swingAngle"]','45');await change('[data-motion-stream="float"]','0');assert.notDeepEqual(await pose(.2),old);await change('[data-motion-stream="cardRatio"]','4:3');await change('[data-motion-stream="motion"]','spin');assert.equal(await page.$eval('[data-stream-swing]',n=>n.hidden),true);await change('[data-motion-config="source"]','scroll');await change('[data-motion-stream="turns"]','3');await change('[data-motion-stream="start"]','20');await change('[data-motion-stream="end"]','80');await change('[data-motion-stream="scrollLength"]','420');assert.equal((await pose(.1))[0].phase,'0.000000');assert.equal((await pose(.5))[0].phase,'1.500000');assert.equal((await pose(.9))[0].phase,'3.000000');assert.deepEqual((await pose(.1)).map(({phase,...n})=>n),(await pose(.9)).map(({phase,...n})=>n));await capture('spin');
  assert.equal(await page.evaluate(()=>JSON.stringify(project)),before.project);assert.equal(await page.evaluate(()=>localStorage.getItem(STORE_KEY)),before.stored);assert.equal(await page.evaluate(()=>history.length),0);
  await page.click('[data-motion-library-tab="library"]');await page.$eval('[data-motion-library-name]',n=>n.value='Mi grilla');await page.click('[data-motion-library-save]');const saved=await page.evaluate(()=>project.nwMotionLibrary.at(-1));assert.equal(saved.config.template,'iso-orbit');assert.equal(saved.config.stream.kind,'iso-orbit');assert.equal(saved.config.stream.spacing,40);assert.equal(saved.assets.length,9);const prepared=await page.evaluate(()=>JSON.stringify(project));const original=await pose(.35);
  await page.click('[data-motion-template="showcase-stream"]');await page.click('[data-motion-template="iso-orbit"]');await ready();assert.equal(await page.$eval('[data-motion-stream="spacing"]',n=>n.value),'40');assert.equal(await page.$eval('[data-motion-stream="motion"]',n=>n.value),'spin');assert.equal((await pose(.35))[0].src,original[0].src);
  await page.click('[data-motion-saved="'+saved.id+'"]');await ready();const copy=await pose(.35);assert.deepEqual(copy.map(({id,...n})=>n),original.map(({id,...n})=>n));assert.ok(copy.every(n=>!original.some(o=>o.id===n.id)),'Library copies have independent IDs');
  await page.click('[data-motion-insert-group]');const inserted=await page.evaluate(()=>{const g=sec().elements.find(e=>e.nwMotionInstance);return{gid:g.id,project:JSON.stringify(project),group:g,members:sec().elements.filter(e=>e.parent===g.id),outside:sec().elements[0],enabled:sec().sdEnabled,length:sec().sdLength};});assert.equal(inserted.group.name,'Mi grilla · composición');assert.equal(inserted.members.length,9);assert.equal(inserted.enabled,true);assert.equal(inserted.length,420);assert.deepEqual(inserted.outside,before.outside);assert.deepEqual(inserted.members.map(e=>e.id),copy.map(n=>n.id));
  await page.waitForFunction(id=>document.querySelector('#preview')?.contentWindow?.__NAG_SCROLL_DIRECTOR?.[id]&&document.querySelector('#preview').contentDocument.querySelector('.nw-orbit-card')?.width>10,{},inserted.gid);await actualScroll('#preview',inserted.gid);await exported(inserted.gid);assert.deepEqual((await pose(.1,'#iso-grid-export',inserted.gid)).map(n=>n.src),copy.map(n=>n.src));await page.$eval('#iso-grid-export',(f,id)=>f.contentWindow.__NAG_SCROLL_DIRECTOR[id].live(),inserted.gid);await actualScroll('#iso-grid-export',inserted.gid);await page.evaluate(()=>document.querySelector('#iso-grid-export').remove());
  await page.evaluate(()=>undo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),prepared);await page.evaluate(()=>redo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),inserted.project);
  await page.evaluate(id=>{NAGWEB_SCROLL_DIRECTOR.scrub(id,.25);NAGWEB_MOTION_LAB.edit(id);},inserted.gid);await ready();await change('[data-motion-stream="spacing"]','52');await page.$eval('#preview',f=>f.contentDocument.body.dataset.orbitSaved='old');await page.click('[data-motion-save]');await page.waitForFunction(id=>{const f=document.querySelector('#preview');return f?.contentDocument?.body&&!f.contentDocument.body.dataset.orbitSaved&&f.contentWindow.__NAG_SCROLL_DIRECTOR?.[id]&&f.contentDocument.querySelector('.nw-orbit-card')?.width>10;},{},inserted.gid);await actualScroll('#preview',inserted.gid);const scrollProject=await page.evaluate(()=>JSON.stringify(project));
  await page.evaluate(id=>NAGWEB_MOTION_LAB.edit(id),inserted.gid);await ready();assert.equal(await page.$eval('[data-motion-stream="spacing"]',n=>n.value),'52');await change('[data-motion-config="source"]','time');await change('[data-motion-config="duration"]','2');await page.click('[data-motion-save]');const loop=await page.evaluate(id=>({project:JSON.stringify(project),enabled:sec().sdEnabled,group:sec().elements.find(e=>e.id===id),outside:sec().elements[0]}),inserted.gid);assert.equal(loop.enabled,false);assert.equal(loop.group.bg,'transparent');assert.equal(loop.group.nwMotionInstance.stream.spacing,52);assert.deepEqual(loop.outside,before.outside);await exported(inserted.gid);const clock=await page.$eval('#iso-grid-export',(f,id)=>f.contentWindow.__NAG_SCROLL_DIRECTOR[id].progress(),inserted.gid);await page.waitForFunction(({gid,clock})=>document.querySelector('#iso-grid-export').contentWindow.__NAG_SCROLL_DIRECTOR[gid].progress()!==clock,{timeout:3000},{gid:inserted.gid,clock});assert.equal(await page.$eval('#iso-grid-export',f=>!!f.contentDocument.querySelector('.nw-sd-active')),false);await page.evaluate(()=>document.querySelector('#iso-grid-export').remove());await page.evaluate(()=>undo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),scrollProject);await page.evaluate(()=>redo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),loop.project);
  await page.setViewport({width:390,height:844,deviceScaleFactor:1});await page.evaluate(()=>NAGWEB_MOTION_LAB.open());await page.click('[data-motion-template="iso-orbit"]');await ready();await change('[data-motion-stream="frameRatio"]','auto');await capture('mobile');const bounds=await page.$eval('.nw-motion-dialog iframe',f=>{const nodes=f.contentDocument.querySelectorAll('[data-nw-stream-slot]'),p=nodes[0].offsetParent;return Array.from(nodes).every(n=>parseFloat(n.style.left)>=0&&parseFloat(n.style.top)>=0&&parseFloat(n.style.left)+parseFloat(n.style.width)<=p.clientWidth&&parseFloat(n.style.top)+parseFloat(n.style.height)<=p.clientHeight);});assert.equal(bounds,true);await page.emulateMediaFeatures([{name:'prefers-reduced-motion',value:'reduce'}]);const still=await pose(.1);assert.deepEqual(await pose(.9),still);await page.emulateMediaFeatures([]);await page.click('[data-motion-close]');await page.setViewport(viewport);assert.equal(await page.evaluate(()=>JSON.stringify(project)),loop.project);
  await page.evaluate(()=>NAGWEB_MOTION_LAB.open());await page.click('[data-motion-template="iso-orbit"]');await ready();await page.click('[data-motion-insert]');const newScene=await page.evaluate(()=>({gid:sec().nwMotionSceneGroup,config:sec().elements.find(e=>e.nwMotionInstance)?.nwMotionInstance}));assert.ok(newScene.gid);assert.equal(newScene.config.template,'iso-orbit');await page.evaluate(id=>NAGWEB_MOTION_LAB.edit(id),newScene.gid);await ready();await page.click('[data-motion-close]');
  console.log('Iso Orbit: imágenes pintadas/selección sobre planos inclinados, nueve posiciones y recursos propios, controles/oscilación/giro/ciclos, borradores y Biblioteca independiente, grupo y escena reeditables, historial, scroll real tras guardar, loop sin Director, transparencia, exportación, móvil y movimiento reducido OK');
 }catch(error){await page.screenshot({path:'/tmp/nagweb-motion-visuals/iso-orbit-failure.png'}).catch(()=>{});throw error;}finally{await page.emulateMediaFeatures([]);await page.setViewport(viewport);await page.evaluate(p=>{document.querySelector('.nw-motion-dialog').close();document.querySelector('#iso-grid-export')?.remove();clearTimeout(previewTimer);project=JSON.parse(p.project);curPage=p.curPage;curSec=p.curSec;curEl=p.curEl;curPane=p.curPane;selection=p.selection;secFocus=p.secFocus;history=[];future=[];NAGWEB_STORY_EDITOR.setCanvasMode(p.mode);NAGWEB_STORY_TIMELINE_UI.setState(p.timeline);saveProject();renderScenes();renderPane();renderPreview();},previous);await fs.rm(dir,{recursive:true,force:true});}
}
